// Serializable narrative state. Rewards only happen on validated transitions.
export const STORY_TITLE='The Captain Who Never Returned';
export const CAST={ines:{name:'Inês Vale',role:'Keeper of the Lantern & Tide',portrait:0,sprite:1},elias:{name:'Elias Ward',role:'Merchant of the London guild',portrait:1,sprite:2},tomas:{name:'Tomás Vale',role:'Captain of the Morning Star',portrait:2,sprite:3},mara:{name:'Mara Chen',role:'Navigator of the Morning Star',portrait:3,sprite:4}};
export function freshStory(){return{phase:'rumor',choice:null,companion:null};}
export function restoreStory(value){const phases=['rumor','compass','charted','return','complete'];if(!phases.includes(value?.phase))return freshStory();const late=['return','complete'].includes(value.phase);if(late&&!['crew','cargo'].includes(value.choice))return freshStory();return{phase:value.phase,choice:late?value.choice:null,companion:value.phase==='complete'?(value.choice==='crew'?'mara':'tomas'):null};}
export function objective(s){switch(s.story.phase){case'rumor':return'Meet Inês at the Lantern & Tide tavern in Lisbon.';case'compass':return'Show the damaged compass to Elias at the merchant guild in London.';case'charted':return'Sail to the Azores. Land at the wreck camp and find Tomás.';case'return':return'Return to Inês in Lisbon with news of her brother.';default:return s.story.choice==='crew'?'Mara is aboard. Your crew uses 20% fewer provisions.':'Tomás is aboard. Repairs at every harbor cost 25% less.';}}
export function storyDestination(s){return s.story.phase==='compass'?'london':s.story.phase==='charted'?'azores':s.story.phase==='complete'?null:'lisbon';}
export function storyItems(s){const p=s.story.phase;return p==='rumor'?[]:[p==='complete'?'The Vale family compass':'Damaged compass',...(['charted','return','complete'].includes(p)?['Elias’s annotated sea chart']:[]),...(s.story.choice==='cargo'?['Recovered captain’s ledger']:[])];}
export function advanceStory(s,action,place){const q=s.story;let message='';if(action==='accept'&&q.phase==='rumor'&&place==='lisbon'){q.phase='compass';message='Inês entrusted you with her brother’s compass. Elias Ward in London may know its emblem.';}else if(action==='chart'&&q.phase==='compass'&&place==='london'){q.phase='charted';message='Elias marked the Morning Star’s last anchorage in the Azores.';}else if(['crew','cargo'].includes(action)&&q.phase==='charted'&&place==='azores'){q.phase='return';q.choice=action;message=action==='crew'?'Rescued the stranded crew. Their stolen cargo disappeared beyond the headland.':'Recovered the stolen cargo and ledger. The crew escaped aboard a passing fishing boat; Mara stayed with them.';}else if(action==='finish'&&q.phase==='return'&&place==='lisbon'){q.phase='complete';q.companion=q.choice==='crew'?'mara':'tomas';const reward=q.choice==='crew'?350:900;s.gold+=reward;message=`Returned to Inês. ${CAST[q.companion].name} joined The Wayfarer. Received ${reward} gold.`;}else return{ok:false,message:'There is nothing more to do here yet.'};s.log.push(message);return{ok:true,message};}
export function conversation(s,id){const p=s.story.phase,c=s.story.choice;const say=(text,choices=[{label:'Until next time.',close:true}])=>({speaker:id,text,choices});
if(id==='ines'){
 if(p==='rumor')return say('Every evening I light that window. Every evening the harbor brings somebody else home. My brother Tomás sailed on the Morning Star six weeks ago. Yesterday, a fisherman brought me this compass. The glass is broken… but I would know his initials anywhere.',[{label:'Tell me about your brother.',next:'brother'},{label:'I’ll find him. Give me the compass.',action:'accept',after:'Then take it. The emblem on its lid belongs to a merchant house in London. Find Elias Ward at the guild. And Captain… bring me the truth, even if it hurts.'},{label:'I’m not ready to leave yet.',close:true}]);
 if(p==='compass')return say('Elias Ward keeps his accounts at the London merchant guild. Show him the compass. Tomás trusted him with every voyage.');
 if(p==='charted')return say('The Azores… he always said the stars looked closer there. Follow Elias’s chart. I’ll keep the lantern burning.');
 if(p==='return')return say(c==='crew'?'Tomás told me what you did. You left a fortune to the tide to bring his people home. Mara is at the door with her charts. She says a captain like you is worth following.':'Tomás brought me his ledger. The stolen wages will feed the sailors’ families, though Mara is still bitter that you chased the cargo first. My brother wants to sail again — this time under your flag.',[{label:c==='crew'?'Welcome Mara aboard · receive 350 gold':'Welcome Tomás aboard · receive 900 gold',action:'finish',after:c==='crew'?'Take this purse, and take good care of her. Mara knows how to stretch a barrel of water through the longest crossing. There will always be a table for you here.':'These are the recovered wages left after the families were paid. Tomás knows every plank of a caravel. Let him bargain with the shipwrights — and remind him to write home.'}]);
 return say(c==='crew'?'Mara sent a letter. She says your crew eats well, even on the longest crossings. My brother is here, mending nets. Some fortunes never fit inside a chest.':'Tomás writes from every harbor now. He tells me he saved you another fortune at the shipyard. Mara still sails with the fishermen. Perhaps, someday, their courses will meet again.');
}
if(id==='elias')return p==='compass'?say('That compass… the silver tern is my seal. I hired the Morning Star to carry wages west. Her last letter spoke of a black-sailed brig near the Azores. Here — an anchorage beneath the old observatory. If the ship survived, that is where I would look.',[{label:'Mark the anchorage on my chart.',action:'chart',after:'The reef has a narrow landing. Look for the wreck camp. The brig is fast; if it is still there, you may have to choose between its cargo and the stranded sailors.'},{label:'I need to prepare first.',close:true}]):say(p==='rumor'?'The Morning Star is overdue. Inês Vale, in Lisbon, has heard more than I have. Speak with her at the Lantern & Tide.':'You have my chart. Whatever you find out there, remember: a ledger measures coin. It does not measure a life.');
if(id==='tomas')return p==='charted'?say('Inês sent you? I thought that compass was lost. The brig took our wages and left us on this reef. Mara’s people are trapped beyond the inlet. The tide is rising — but the thieves are weighing anchor too. We cannot reach both in time.',[{label:'Rescue the crew. Let the cargo go.',next:'crew'},{label:'Pursue the stolen cargo.',next:'cargo'},{label:'Let me think.',close:true}]):say(c==='crew'?'You brought every one of them back. Mara has already asked about a berth on your ship. Take me home to my sister, Captain.':'The ledger and wages are safe. A fishing boat picked up the others, but Mara would not look at me. Take me home. I need to see Inês.');
return say(p==='charted'?'There are six sailors beyond the inlet. I can guide your boat through the reef, but we must move before the next tide.':'I’ll never forget this crossing. A captain’s choices travel farther than their ship.');
}
export function conversationBranch(s,id,branch){if(branch==='brother')return{speaker:id,text:'He remembers every sailor’s birthday and forgets his own. He drew maps on my tables as a boy. I used to scold him for it. Now I would give anything to find another ink stain.',choices:[{label:'I’ll take the compass and find him.',action:'accept',after:'Find Elias Ward at the merchant guild in London. He will recognize the emblem. Thank you, Captain.'},{label:'I need more time.',close:true}]};const crew=branch==='crew';return{speaker:id,text:crew?'You commit your boats to the reef. All six sailors can be saved, but the brig will escape with the wages. Mara will remember that you put her crew first.':'You commit your ship to the chase. You can recover the wages and the captain’s ledger, but the stranded crew must rely on a distant fishing boat. Mara will not join you.',choices:[{label:crew?'Launch the rescue boats':'Set sail after the brig',action:crew?'crew':'cargo',after:crew?'Through salt spray and broken spars, your boats reach the inlet. Six exhausted sailors climb aboard. On the horizon, the brig vanishes. Mara grips your hand: “You came back for us.” Return to Inês in Lisbon.':'Your broadside turns the brig from the channel. The thieves abandon the wage chest and ledger. At dusk, a fishing boat brings the crew to safety. Mara stays with them. Tomás boards your ship in silence. Return to Inês in Lisbon.'},{label:'Reconsider.',next:'start'}]};}

export function repairCost(s){return Math.ceil((100-s.hull)*3*(s.story.companion==='tomas'?.75:1));}
export function provisionRate(s){return s.story.companion==='mara'?.8:1;}
